using namespace Gdiplus;
struct Pixel { BYTE b,g,r,a; };
struct Photo {int w=0,h=0; std::vector<Pixel> p; bool empty()const{return p.empty();}};
Photo img,orig,preview; bool previewActive=false; int sidebarOffset=0; std::vector<Photo> history; std::wstring filename; HWND win,status,sl[6],labelControls[6]; bool before=false,heal=false,pick=false,centerMode=false; RECT view; int vx,vy,vw,vh; double centerX=.5,centerY=.5; HBRUSH bg, panel; HFONT font,titleFont; COLORREF backgroundColor=RGB(255,255,255); int sliderValues[6]={0,0,0,0,0,35};
int clamp(int x){return std::max(0,std::min(255,x));}
void tell(std::wstring s){SetWindowTextW(status,s.c_str());}
void resetSliders(){previewActive=false;preview=Photo();KillTimer(win,1);for(int i=0;i<6;i++){SendMessage(sl[i],TBM_SETPOS,TRUE,sliderValues[i]);}}
void refresh(){InvalidateRect(win,0,FALSE);}
void remember(){if(!img.empty()){size_t bytes=0;for(auto &h:history)bytes+=h.p.size()*4;while(!history.empty()&&(history.size()>=6||bytes+img.p.size()*4>256*1024*1024)){bytes-=history.front().p.size()*4;history.erase(history.begin());}history.push_back(img);}}
Photo readImage(const std::wstring& path){Bitmap b(path.c_str()); if(b.GetLastStatus()!=Ok)throw std::runtime_error("image");UINT w=b.GetWidth(),h=b.GetHeight(); if(!w||!h|| (uint64_t)w*h>40000000)throw std::runtime_error("size"); UINT propertySize=b.GetPropertyItemSize(PropertyTagOrientation);if(propertySize){std::vector<BYTE> prop(propertySize);auto item=(PropertyItem*)prop.data();if(b.GetPropertyItem(PropertyTagOrientation,propertySize,item)==Ok&&item->length>=2){WORD o=*(WORD*)item->value;RotateFlipType types[]={RotateNoneFlipNone,RotateNoneFlipNone,RotateNoneFlipX,Rotate180FlipNone,RotateNoneFlipY,Rotate90FlipX,Rotate90FlipNone,Rotate270FlipX,Rotate270FlipNone};if(o>=2&&o<=8)b.RotateFlip(types[o]);w=b.GetWidth();h=b.GetHeight();}}Bitmap copy(w,h,PixelFormat32bppARGB);{Graphics g(&copy);g.DrawImage(&b,0,0,w,h);}Photo out;out.w=w;out.h=h;out.p.resize((size_t)w*h);BitmapData d;Rect r(0,0,w,h);if(copy.LockBits(&r,ImageLockModeRead,PixelFormat32bppARGB,&d)!=Ok)throw std::runtime_error("lock");for(UINT y=0;y<h;y++)memcpy(out.p.data()+y*w,(BYTE*)d.Scan0+y*d.Stride,w*4);copy.UnlockBits(&d);return out;}
void load(std::wstring path){try{Photo next=readImage(path);img=std::move(next);orig=img;filename=path;history.clear();before=false;heal=pick=centerMode=false;centerX=centerY=.5;resetSliders();tell(L"Открыто • "+std::to_wstring(img.w)+L" × "+std::to_wstring(img.h)+L" • Оригинал остаётся без изменений");refresh();}catch(...){MessageBox(win,L"Не удалось открыть изображение. Поддерживаются JPG, PNG, BMP, TIFF и GIF. Лимит — 40 мегапикселей.",L"Открытие фотографии",MB_ICONWARNING);}}
std::wstring fileDialog(bool save=false){wchar_t path[32768]=L"";OPENFILENAME o={sizeof(o)};o.hwndOwner=win;o.lpstrFilter=save?L"PNG — с прозрачностью\0*.png\0JPEG — фотография\0*.jpg\0":L"Фотографии\0*.jpg;*.jpeg;*.png;*.bmp;*.tif;*.tiff;*.gif\0Все файлы\0*.*\0";o.lpstrFile=path;o.nMaxFile=32768;o.Flags=OFN_EXPLORER|OFN_PATHMUSTEXIST|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);o.lpstrDefExt=save?L"png":0;if((save?GetSaveFileName(&o):GetOpenFileName(&o)))return path;return L"";}
bool saveImage(const Photo& im,const std::wstring& path){std::wstring ext=path.substr(path.find_last_of(L'.')+1);std::transform(ext.begin(),ext.end(),ext.begin(),::towlower);if(ext!=L"png"&&ext!=L"jpg"&&ext!=L"jpeg")return false;Photo flat=im;if(ext!=L"png")for(auto &p:flat.p){p.r=(p.r*p.a+255*(255-p.a))/255;p.g=(p.g*p.a+255*(255-p.a))/255;p.b=(p.b*p.a+255*(255-p.a))/255;p.a=255;}Bitmap b(flat.w,flat.h,flat.w*4,PixelFormat32bppARGB,(BYTE*)flat.p.data());b.SetResolution(300,300);UINT size=0,n=0;GetImageEncodersSize(&n,&size);std::vector<BYTE> buf(size);auto enc=(ImageCodecInfo*)buf.data();GetImageEncoders(n,size,enc);CLSID id={};for(UINT i=0;i<n;i++)if(wcscmp(enc[i].MimeType,ext==L"png"?L"image/png":L"image/jpeg")==0)id=enc[i].Clsid;ULONG q=95;EncoderParameters ep;ep.Count=1;ep.Parameter[0].Guid=EncoderQuality;ep.Parameter[0].Type=EncoderParameterValueTypeLong;ep.Parameter[0].NumberOfValues=1;ep.Parameter[0].Value=&q;return b.Save(path.c_str(),&id,&ep)==Ok;}
void autoCorrect(Photo &im){int hist[3][256]={};int count=0;for(auto p:im.p)if(p.a>128){hist[0][p.r]++;hist[1][p.g]++;hist[2][p.b]++;count++;}if(!count)return;int lo[3],hi[3];for(int c=0;c<3;c++){int a=0;lo[c]=0;hi[c]=255;for(int v=0;v<256;v++){a+=hist[c][v];if(a>count/100){lo[c]=v;break;}}a=0;for(int v=255;v>=0;v--){a+=hist[c][v];if(a>count/100){hi[c]=v;break;}}}for(auto &p:im.p){BYTE* channels[]={&p.r,&p.g,&p.b};for(int c=0;c<3;c++)if(hi[c]-lo[c]>24){double normalized=(*channels[c]-lo[c])*255.0/(hi[c]-lo[c]);*channels[c]=clamp((int)(.75*normalized+.25**channels[c]));}}}
void smooth(Photo& im,int strength){if(!strength)return;Photo src=im;double k=strength/100.;for(int y=1;y<im.h-1;y++)for(int x=1;x<im.w-1;x++){Pixel p=src.p[y*im.w+x];double r=0,g=0,b=0,total=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){auto q=src.p[(y+dy)*im.w+x+dx];int diff=abs(p.r-q.r)+abs(p.g-q.g)+abs(p.b-q.b);double w=exp(-diff*diff/(1800.+strength*65.));r+=q.r*w;g+=q.g*w;b+=q.b*w;total+=w;}auto &o=im.p[y*im.w+x];o.r=clamp(p.r*(1-k)+r/total*k);o.g=clamp(p.g*(1-k)+g/total*k);o.b=clamp(p.b*(1-k)+b/total*k);}}
void sharpen(Photo& im,int strength){if(!strength)return;Photo src=im;double k=strength/100.;for(int y=1;y<im.h-1;y++)for(int x=1;x<im.w-1;x++){int idx=y*im.w+x;auto p=src.p[idx];int r=0,g=0,b=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){auto q=src.p[(y+dy)*im.w+x+dx];r+=q.r;g+=q.g;b+=q.b;}im.p[idx].r=clamp(p.r+k*(p.r-r/9.));im.p[idx].g=clamp(p.g+k*(p.g-g/9.));im.p[idx].b=clamp(p.b+k*(p.b-b/9.));}}
void adjust(Photo& im,int light,int contrast,int sat){double c=pow(2.,contrast/65.);for(auto &p:im.p){double l=.2126*p.r+.7152*p.g+.0722*p.b;double s=1+sat/100.;p.r=clamp((int)(((l+(p.r-l)*s)-128)*c+128+light*1.6));p.g=clamp((int)(((l+(p.g-l)*s)-128)*c+128+light*1.6));p.b=clamp((int)(((l+(p.b-l)*s)-128)*c+128+light*1.6));}}
bool pending(){for(int i=0;i<5;i++)if(SendMessage(sl[i],TBM_GETPOS,0,0))return true;return false;}
void settings(Photo& im){adjust(im,SendMessage(sl[0],TBM_GETPOS,0,0),SendMessage(sl[1],TBM_GETPOS,0,0),SendMessage(sl[2],TBM_GETPOS,0,0));smooth(im,SendMessage(sl[3],TBM_GETPOS,0,0));sharpen(im,SendMessage(sl[4],TBM_GETPOS,0,0));}
void commitSettings(){if(pending()){remember();settings(img);resetSliders();}}
void updatePreview(){if(img.empty())return;previewActive=pending();if(previewActive){double k=std::min(1.,900./std::max(img.w,img.h));preview.w=std::max(1,(int)(img.w*k));preview.h=std::max(1,(int)(img.h*k));preview.p.resize(preview.w*preview.h);for(int y=0;y<preview.h;y++)for(int x=0;x<preview.w;x++)preview.p[y*preview.w+x]=img.p[std::min(img.h-1,(int)(y/k))*img.w+std::min(img.w-1,(int)(x/k))];settings(preview);tell(L"Предпросмотр настроек • «Применить» закрепит изменения; при сохранении они применятся автоматически.");}refresh();}
void scrollSidebar(int target){RECT rc;GetClientRect(win,&rc);target=std::max(0,std::min(std::max(0,850-(int)(rc.bottom-rc.top)),target));int delta=sidebarOffset-target;sidebarOffset=target;for(HWND child=GetWindow(win,GW_CHILD);child;child=GetWindow(child,GW_HWNDNEXT)){RECT r;GetWindowRect(child,&r);MapWindowPoints(0,win,(POINT*)&r,2);if(r.left<278)SetWindowPos(child,0,r.left,r.top+delta,0,0,SWP_NOSIZE|SWP_NOZORDER|SWP_NOACTIVATE);}SCROLLINFO si={sizeof(si),SIF_RANGE|SIF_PAGE|SIF_POS,0,849,(UINT)(rc.bottom-rc.top),sidebarOffset,0};SetScrollInfo(win,SB_VERT,&si,TRUE);refresh();}
void restore(Photo& im){autoCorrect(im);Photo src=im;for(int y=1;y<im.h-1;y++)for(int x=1;x<im.w-1;x++){int rr[9],gg[9],bb[9],n=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){auto p=src.p[(y+dy)*im.w+x+dx];rr[n]=p.r;gg[n]=p.g;bb[n++]=p.b;}std::sort(rr,rr+9);std::sort(gg,gg+9);std::sort(bb,bb+9);auto &p=im.p[y*im.w+x];if(abs(p.r-rr[4])+abs(p.g-gg[4])+abs(p.b-bb[4])>110){p.r=rr[4];p.g=gg[4];p.b=bb[4];}}smooth(im,30);sharpen(im,20);}
void removeBackground(int sx,int sy){remember();Pixel key=img.p[sy*img.w+sx];int tolerance=SendMessage(sl[5],TBM_GETPOS,0,0);std::vector<BYTE> seen(img.p.size());std::vector<int> queue;auto add=[&](int i){if(seen[i])return;seen[i]=1;auto p=img.p[i];double d=sqrt((p.r-key.r)*(p.r-key.r)+(p.g-key.g)*(p.g-key.g)+(p.b-key.b)*(p.b-key.b))/1.732;if(d<=tolerance*2.55){queue.push_back(i);img.p[i].a=0;}};add(sy*img.w+sx);for(int x=0;x<img.w;x++){add(x);add((img.h-1)*img.w+x);}for(int y=0;y<img.h;y++){add(y*img.w);add(y*img.w+img.w-1);}for(size_t pos=0;pos<queue.size();pos++){int i=queue[pos],x=i%img.w,y=i/img.w;if(x)add(i-1);if(x<img.w-1)add(i+1);if(y)add(i-img.w);if(y<img.h-1)add(i+img.w);}tell(L"Фон удалён по выбранному цвету. PNG сохраняет прозрачность. Можно отменить и изменить допуск.");}
void healAt(int x,int y){remember();int radius=std::max(3,std::min(img.w,img.h)/90);Photo src=img;double r=0,g=0,b=0,n=0;for(int dy=-radius*2;dy<=radius*2;dy++)for(int dx=-radius*2;dx<=radius*2;dx++){double d=sqrt(dx*dx+dy*dy);int xx=x+dx,yy=y+dy;if(d>=radius*1.2&&d<=radius*1.9&&xx>=0&&yy>=0&&xx<img.w&&yy<img.h){auto p=src.p[yy*img.w+xx];r+=p.r;g+=p.g;b+=p.b;n++;}}if(!n)return;for(int dy=-radius;dy<=radius;dy++)for(int dx=-radius;dx<=radius;dx++){double d=sqrt(dx*dx+dy*dy)/radius;int xx=x+dx,yy=y+dy;if(d<1&&xx>=0&&yy>=0&&xx<img.w&&yy<img.h){auto &p=img.p[yy*img.w+xx];double a=(1-d*d);p.r=clamp(p.r*(1-a)+r/n*a);p.g=clamp(p.g*(1-a)+g/n*a);p.b=clamp(p.b*(1-a)+b/n*a);}}tell(L"Дефект смягчён. Нажимайте на небольшие дефекты кожи; «Отменить» возвращает предыдущий шаг.");}
void document(){remember();double aspect=35./45.;int w=img.w,h=(int)(w/aspect);if(h>img.h){h=img.h;w=(int)(h*aspect);}int x=std::max(0,std::min(img.w-w,(int)(centerX*img.w-w/2)));int y=std::max(0,std::min(img.h-h,(int)(centerY*img.h-h/2)));Photo out;out.w=413;out.h=531;out.p.resize(out.w*out.h);Bitmap source(img.w,img.h,img.w*4,PixelFormat32bppARGB,(BYTE*)img.p.data());Bitmap dest(out.w,out.h,PixelFormat32bppARGB);{Graphics g(&dest);g.SetInterpolationMode(InterpolationModeHighQualityBicubic);g.DrawImage(&source,Rect(0,0,out.w,out.h),x,y,w,h,UnitPixel);}BitmapData d;Rect rc(0,0,out.w,out.h);dest.LockBits(&rc,ImageLockModeRead,PixelFormat32bppARGB,&d);for(int yy=0;yy<out.h;yy++)memcpy(out.p.data()+yy*out.w,(BYTE*)d.Scan0+yy*d.Stride,out.w*4);dest.UnlockBits(&d);img=std::move(out);tell(L"Кадр 35 × 45 мм, 413 × 531 пикселей (300 dpi). Проверьте требования ведомства к позе и размеру головы.");}
void batch(){wchar_t paths[65536]={};OPENFILENAME o={sizeof(o)};o.hwndOwner=win;o.lpstrFilter=L"Фотографии\0*.jpg;*.jpeg;*.png;*.bmp;*.tif;*.tiff\0";o.lpstrFile=paths;o.nMaxFile=65536;o.Flags=OFN_ALLOWMULTISELECT|OFN_EXPLORER|OFN_FILEMUSTEXIST;if(!GetOpenFileName(&o))return;std::vector<std::wstring> files;std::wstring dir=paths;wchar_t* p=paths+dir.size()+1;if(!*p)files.push_back(dir);else while(*p){files.push_back(dir+L"\\"+p);p+=wcslen(p)+1;}if(MessageBox(win,L"Выполнить автокоррекцию, мягкое удаление шума и повышение резкости?\n\nРезультаты PNG появятся в папке PhotoMaster_Output рядом с каждым оригиналом. Существующие файлы не перезаписываются.",L"Пакетная обработка",MB_OKCANCEL|MB_ICONINFORMATION)!=IDOK)return;SetCursor(LoadCursor(0,IDC_WAIT));int ok=0,failed=0;for(auto path:files){try{Photo im=readImage(path);autoCorrect(im);smooth(im,35);sharpen(im,30);auto slash=path.find_last_of(L"\\/");std::wstring folder=path.substr(0,slash)+L"\\PhotoMaster_Output";CreateDirectory(folder.c_str(),0);std::wstring base=path.substr(slash+1);auto dot=base.find_last_of(L'.');if(dot!=std::wstring::npos)base.resize(dot);std::wstring output=folder+L"\\"+base+L"_enhanced.png";int n=2;while(GetFileAttributes(output.c_str())!=INVALID_FILE_ATTRIBUTES)output=folder+L"\\"+base+L"_enhanced_"+std::to_wstring(n++)+L".png";if(saveImage(im,output))ok++;else failed++;}catch(...){failed++;}}SetCursor(LoadCursor(0,IDC_ARROW));MessageBox(win,(L"Сохранено: "+std::to_wstring(ok)+L"\nОшибок: "+std::to_wstring(failed)+L"\nРезультаты: PhotoMaster_Output рядом с оригиналами.").c_str(),L"Готово",MB_OK);}
void setBackground(bool photo){if(img.empty())return;if(photo){auto path=fileDialog();if(path.empty())return;try{auto b=readImage(path);remember();double scale=std::max(img.w/(double)b.w,img.h/(double)b.h);for(int y=0;y<img.h;y++)for(int x=0;x<img.w;x++){int xx=std::max(0,std::min(b.w-1,(int)((x-img.w/2.)/scale+b.w/2.)));int yy=std::max(0,std::min(b.h-1,(int)((y-img.h/2.)/scale+b.h/2.)));auto &p=img.p[y*img.w+x];auto q=b.p[yy*b.w+xx];p.r=(p.r*p.a+q.r*(255-p.a))/255;p.g=(p.g*p.a+q.g*(255-p.a))/255;p.b=(p.b*p.a+q.b*(255-p.a))/255;p.a=255;}}catch(...){tell(L"Не удалось открыть фон.");}}else{static COLORREF custom[16]={};CHOOSECOLOR c={sizeof(c)};c.hwndOwner=win;c.rgbResult=backgroundColor;c.lpCustColors=custom;c.Flags=CC_FULLOPEN|CC_RGBINIT;if(!ChooseColor(&c))return;backgroundColor=c.rgbResult;remember();for(auto &p:img.p){p.r=(p.r*p.a+GetRValue(backgroundColor)*(255-p.a))/255;p.g=(p.g*p.a+GetGValue(backgroundColor)*(255-p.a))/255;p.b=(p.b*p.a+GetBValue(backgroundColor)*(255-p.a))/255;p.a=255;}}tell(L"Фон заменён. Можно отменить действие.");refresh();}
void action(int id){if(id==100){auto p=fileDialog();if(!p.empty())load(p);return;}if(id==116){batch();return;}if(id==120){MessageBox(win,L"PhotoMaster AI • локальный фоторедактор\n\nВсе операции выполняются на компьютере. Программа не содержит сетевых функций и не отправляет фотографии.\n\nЗдесь используются классические алгоритмы, без нейросетевой модели: автокоррекция, фильтрация шума, резкость, точечная ретушь и удаление связного фона по цвету. Для сложного фона результат ограничен.\n\nРеставрация улучшает выцветшие снимки и мелкие точки, но не воссоздаёт утраченные детали. Геометрия лица не изменяется.\n\nОткрытие: JPG, PNG, BMP, TIFF, GIF (первый кадр), до 40 Мп. Экспорт: JPG и PNG.\n\nСравнение: кнопка «До / после» или удержание пробела. Ретушь и фон: включите инструмент, затем нажмите на фото.\n\nДля документов: сначала выберите центр кадра, затем нажмите 35 × 45. Это подготовка кадра, а не гарантия приёма документа.",L"О программе и возможностях",MB_OK);return;}if(img.empty()){tell(L"Сначала откройте фотографию или перетащите её в окно.");return;}if(id==110&&pending()){resetSliders();tell(L"Предпросмотр отменён.");refresh();return;}if(id!=104&&id!=109&&id!=110&&id!=111)commitSettings();if(id==111||id==110)resetSliders();SetCursor(LoadCursor(0,IDC_WAIT));heal=pick=centerMode=false;before=false;switch(id){case 101:{auto p=fileDialog(true);if(!p.empty()){if(saveImage(img,p))tell(L"Сохранено: "+p);else MessageBox(win,L"Не удалось сохранить. Выберите расширение .png или .jpg и доступную папку.",L"Сохранение",MB_ICONWARNING);}break;}case 102:remember();autoCorrect(img);smooth(img,25);sharpen(img,25);tell(L"Улучшение применено • цвет, мягкий шумодав и резкость");break;case 103:remember();autoCorrect(img);tell(L"Автокоррекция применена.");break;case 104:commitSettings();tell(L"Настройки применены. Для возврата нажмите «Отменить».");break;case 105:heal=true;tell(L"Ретушь: нажмите на небольшой прыщ или точечный дефект. Размер кисти зависит от размера снимка.");break;case 106:pick=true;tell(L"Удаление фона: нажмите на цвет фона. Для сложного снимка подберите допуск и повторите после отмены.");break;case 107:setBackground(false);break;case 108:remember();restore(img);tell(L"Реставрация: исправлены цвет и мелкие точечные повреждения. Большие царапины обрабатывайте ретушью.");break;case 109:before=true;tell(L"Показан оригинал. Нажмите «До / после» ещё раз, чтобы вернуться.");break;case 110:if(!history.empty()){img=std::move(history.back());history.pop_back();tell(L"Последнее действие отменено.");}break;case 111:remember();img=orig;tell(L"Возвращён оригинал.");break;case 112:centerMode=true;tell(L"Нажмите на центр будущего кадра 35 × 45, затем нажмите «Кадр 35 × 45».");break;case 113:document();break;case 114:setBackground(true);break;}SetCursor(LoadCursor(0,IDC_ARROW));refresh();}
HWND button(int id,const wchar_t* text,int x,int y,int w,int h){HWND b=CreateWindow(L"BUTTON",text,WS_CHILD|WS_VISIBLE|BS_OWNERDRAW,x,y,w,h,win,(HMENU)(INT_PTR)id,0,0);SendMessage(b,WM_SETFONT,(WPARAM)font,TRUE);return b;}
void paint(){PAINTSTRUCT ps;HDC dc=BeginPaint(win,&ps);RECT client;GetClientRect(win,&client);FillRect(dc,&client,bg);RECT side={0,0,278,client.bottom};FillRect(dc,&side,panel);SetBkMode(dc,TRANSPARENT);SetTextColor(dc,RGB(235,240,250));SelectObject(dc,titleFont);TextOut(dc,22,20-sidebarOffset,L"PhotoMaster AI",14);SelectObject(dc,font);SetTextColor(dc,RGB(145,156,179));TextOut(dc,23,54-sidebarOffset,L"ЛОКАЛЬНЫЙ ФОТОРЕДАКТОР",(int)wcslen(L"ЛОКАЛЬНЫЙ ФОТОРЕДАКТОР"));view={296,24,client.right-22,client.bottom-70};FillRect(dc,&view,bg);if(!img.empty()){const Photo &im=before?orig:(previewActive?preview:img);double scale=std::min((view.right-view.left)/(double)im.w,(view.bottom-view.top)/(double)im.h);vw=std::max(1,(int)(im.w*scale));vh=std::max(1,(int)(im.h*scale));vx=view.left+(view.right-view.left-vw)/2;vy=view.top+(view.bottom-view.top-vh)/2;Graphics g(dc);for(int yy=vy;yy<vy+vh;yy+=16)for(int xx=vx;xx<vx+vw;xx+=16){SolidBrush brush(((xx-vx)/16+(yy-vy)/16)%2?Color(255,61,65,76):Color(255,49,53,63));g.FillRectangle(&brush,xx,yy,std::min(16,vx+vw-xx),std::min(16,vy+vh-yy));}Bitmap bitmap(im.w,im.h,im.w*4,PixelFormat32bppARGB,(BYTE*)im.p.data());g.SetInterpolationMode(InterpolationModeHighQualityBicubic);g.DrawImage(&bitmap,vx,vy,vw,vh);if(centerMode){Pen pen(Color(255,140,125,255),2);float cx=vx+centerX*vw,cy=vy+centerY*vh;g.DrawLine(&pen,cx-18,cy,cx+18,cy);g.DrawLine(&pen,cx,cy-18,cx,cy+18);}SetTextColor(dc,RGB(200,205,220));TextOut(dc,view.left,client.bottom-52,before?L"ОРИГИНАЛ • ДО":L"РЕЗУЛЬТАТ • ПОСЛЕ",before?(int)wcslen(L"ОРИГИНАЛ • ДО"):(int)wcslen(L"РЕЗУЛЬТАТ • ПОСЛЕ"));}else{SetTextColor(dc,RGB(208,216,236));RECT text=view;DrawText(dc,L"Перетащите фотографию сюда\n\nили нажмите «Открыть фото»\n\nJPG · PNG · BMP · TIFF\n\nВсе фотографии остаются на вашем компьютере",-1,&text,DT_CENTER|DT_WORDBREAK);}EndPaint(win,&ps);}
